class Solution {
    public int slotFor(int[] shelf, int book) {
        // Lower bound (first slot with val >= book)
        // Insert slot = count of books below book
        // Binary search keeps slot inside [lo, hi]
        // hi = shelf.length, not last index (slot after last book is valid)
        int lo = 0, hi = shelf.length;
        while (lo < hi) {
            // middle, rounded down (no lo + hi overflow)
            int mid = lo + (hi - lo) / 2;
            // mid book below new one, so slot is right of mid
            if (shelf[mid] < book) lo = mid + 1;
            // mid could be slot, so keep it (hi = mid, not mid - 1)
            else hi = mid;
        }
        return lo;
    }
}

