class Solution {
    public int slotFor(int[] shelf, int book) {
        // Library lower bound (first slot with val >= book)
        int pos = Arrays.binarySearch(shelf, book);
        // absent book returns -(slot) - 1, so decode with -pos - 1
        return pos >= 0 ? pos : -pos - 1;
    }
}

