class Solution {
public:
    int findTag(vector<int>& carousel, int tag) {
        // Find rotation start (index of minimum)
        // Tag can only be in one sorted run, so binary search that run
        int n = carousel.size(), lo = 0, hi = n - 1;
        while (lo < hi) {
            // middle, rounded down (no lo + hi overflow)
            int mid = lo + (hi - lo) / 2;
            // mid val above hi val, so drop is right of mid
            if (carousel[mid] > carousel[hi]) lo = mid + 1;
            // mid could be minimum, so keep it (hi = mid, not mid - 1)
            else hi = mid;
        }
        // rotation start (index of minimum)
        int start = lo;
        // run [0, start) unless tag is in [start, n)
        auto first = carousel.begin(), last = carousel.begin() + start;
        // tag within val range of [start, n), so search that run
        if (carousel[start] <= tag && tag <= carousel[n - 1]) {
            first = carousel.begin() + start;
            last = carousel.end();
        }
        // lower bound in run (half-open [first, last))
        auto it = lower_bound(first, last, tag);
        // lower bound can land past run end or on bigger val
        return it != last && *it == tag ? int(it - carousel.begin()) : -1;
    }
};

