class Solution {
    public double combinedMedian(int[] a, int[] b) {
        // Cut both arrays (cutA + cutB = leftSize)
        // Valid cut (all left vals <= all right vals)
        // Median at valid cut index
        // Binary search cutA in shorter array
        // If cutA too big it breaks aLeft <= bRight; if too small it breaks bLeft <= aRight
        if (a.length > b.length) return combinedMedian(b, a);
        int m = a.length, n = b.length;
        // +1 so odd total keeps median on left
        int leftSize = (m + n + 1) / 2;
        int lo = 0, hi = m;
        while (lo <= hi) {
            int cutA = (lo + hi) / 2, cutB = leftSize - cutA;
            // vals beside each cut (MIN/MAX_VALUE if side empty)
            int aLeft = cutA > 0 ? a[cutA - 1] : Integer.MIN_VALUE;
            int aRight = cutA < m ? a[cutA] : Integer.MAX_VALUE;
            int bLeft = cutB > 0 ? b[cutB - 1] : Integer.MIN_VALUE;
            int bRight = cutB < n ? b[cutB] : Integer.MAX_VALUE;
            // arrays sorted, so only cross pairs can fail
            if (aLeft <= bRight && bLeft <= aRight) {
                int leftMax = Math.max(aLeft, bLeft);
                if ((m + n) % 2 == 1) return leftMax;
                // even total = average of two middle vals
                // cast to double first (no int overflow, keeps .5)
                return ((double) leftMax + Math.min(aRight, bRight)) / 2.0;
            }
            // too many from a
            if (aLeft > bRight) hi = cutA - 1;
            // too few from a
            else lo = cutA + 1;
        }
        return 0.0;  // unreachable
    }
}

